mapper.select:
	select
		CD_DTL_ID, CD_ID, CD_DTL_NM, CD_DTL_LABEL, CD_DTL_ORD, CD_DTL_DESC, REC_ST, CD_DTL_ACTIVE_ICON, CD_DTL_INACTIVE_ICON, CD_DTL_CUSTOM_INT, REG_ID, REG_DT, UPD_ID, UPD_DT
	from
		JCMS_CD_DTL
	where
		DEL_DT IS NULL
		 and CD_ID = #{cdId,jdbcType=VARCHAR} 
		 and REC_ST = #{recSt} 
	 order by ${sort} ${sortOrd} 
     limit #{start}, #{length}
